watch(servicePages,count=>servicePage.value=Math.min(servicePage.value,count))
watch([()=>w.project.value,()=>w.hours.value,currentPage],closeHover)
watch(()=>w.displayTarget.value,()=>{if(keepOpen.value&&hoverNode.value){activeRound.value=null;inlineTab.value='history'}else closeHover()})
onMounted(()=>monitorTimer=setInterval(()=>{if(w.page.value==='home'&&document.visibilityState==='visible')void readMonitor()},30000));onBeforeUnmount(()=>{qualityGeneration++;presentation.clear();monitorGeneration++;clearTimeout(hoverTimer);clearInterval(monitorTimer)})
</script>
<template>
  <section class="home-view" :class="{'quality-view':qualityView,'quality-history-visible':qualityHistory,'filters-expanded':extraFiltersOpen}" @keydown.esc="closeExtraFilters">
    <div class="home-top"><div><h1>{{qualityView?'快速筛选 · 节点质量比较':'六站详细视图'}}</h1><p>以真实证据筛选；样本不足不评分。</p></div><nav class="view-switch home-layout-switch" aria-label="首页视图"><button :aria-pressed="qualityView" @click="changeView(true)">快速筛选 / 节点质量比较</button><button :aria-pressed="!qualityView" @click="changeView(false)">六站详细视图</button></nav><button class="button ghost" :disabled="w.loading.value" @click="w.refreshNodes().catch(w.fail)"><Icon name="refresh"/>重新载入列表</button></div>
    <section class="source-orbit" aria-label="机场选择">
      <div class="orbit-shell"><svg viewBox="0 0 240 240" class="orbit-ring" aria-hidden="true"><circle cx="120" cy="120" r="115" class="orbit-track"/><circle v-for="(airport,i) in chosen" :key="airport.id" cx="120" cy="120" r="115" class="orbit-segment" :stroke-dasharray="`${2*Math.PI*115/Math.max(1,chosen.length)-10} ${2*Math.PI*115-2*Math.PI*115/Math.max(1,chosen.length)+10}`" :stroke-dashoffset="-i*2*Math.PI*115/Math.max(1,chosen.length)"/></svg><button class="orbit-button" :aria-label="'选择机场：'+(chosenNames||'尚未选择')" :aria-expanded="picker" @click="picker=true"><span class="airport-logos"><span v-for="airport in chosen.slice(0,4)" :key="airport.id" class="airport-logo">{{airport.name.slice(0,1)}}</span><span v-if="chosen.length>4" class="airport-logo airport-logo-more">+{{chosen.length-4}}</span><Icon v-if="!chosen.length" name="plus"/></span><strong>{{chosen.length?`${chosen.length} 个机场`:'选择机场'}}</strong><span class="orbit-names" :title="chosenNames">{{chosen.length>3?chosen.slice(0,2).map(a=>a.name).join(' · ')+' 等 '+chosen.length+' 个':chosenNames||'支持同时选择多个'}}</span><span class="orbit-link">切换机场<Icon name="down"/></span></button></div>
      <div class="orbit-meta"><span><strong>{{w.proxyNodes.value.length}}</strong> 个节点</span><span><strong>{{profiles.length}}</strong> 个订阅</span><button v-if="w.notices.value.length" class="text-button" @click="noticeOpen=true">{{w.notices.value.length}} 条公告</button></div>
    </section>
    <div class="home-controls" :class="{following:followControls}">
    <nav class="project-tabs" aria-label="检测项目"><button v-for="p in (['latency','download','service','combined'] as Project[])" :key="p" :aria-selected="w.project.value===p" @click="w.project.value=p"><Icon :name="p==='latency'?'pulse':p==='download'?'download':p==='service'?'globe':'layers'"/>{{projectNames[p]}}</button><label class="follow-controls-switch" title="开启后，检测和筛选选项会在滚动时留在顶部"><input v-model="followControls" type="checkbox" aria-label="跟随滚动"><Icon name="pin"/>跟随滚动</label><button class="tab-tail" :disabled="!runNodes.length||w.busy.value||qualityFiltersPending" @click="openCombinedPlan"><Icon name="settings"/>组合检测 · {{w.selectedNodes.value.length?'已选':'筛选'}} {{runNodes.length}} 个</button></nav>
    <div class="view-context">
      <div id="home-context-filters" class="context-controls">
        <label v-if="qualityView">质量统计站点<UiSelect v-model="w.displayTarget.value" aria-label="质量统计站点"><option v-for="site in targets" :key="site.id" :value="site.id">{{site.name}}</option></UiSelect></label><SiteDisplayPicker v-if="!qualityView&&(w.project.value==='latency'||w.project.value==='combined')" v-model="w.displayTargets.value"/>
        
        <SiteDisplayPicker v-if="w.project.value==='service'||w.project.value==='combined'" v-model="w.displayServiceIds.value" :choices="serviceChoices" label="显示服务" item-label="服务" :default-id="serviceChoices[0]?.id"/>
        <span v-if="(w.project.value==='service'||w.project.value==='combined')&&servicePages>1" class="service-display-pages" aria-label="显示服务分组"><button class="text-button" :disabled="servicePage<=1" aria-label="上一组服务" @click="servicePage--">‹</button><span>{{(servicePage-1)*servicesPerPage+1}}–{{Math.min(servicePage*servicesPerPage,displayServices.length)}} / {{displayServices.length}} 项</span><button class="text-button" :disabled="servicePage>=servicePages" aria-label="下一组服务" @click="servicePage++">›</button></span>
        <label>历史范围<UiSelect v-model.number="w.hours.value"><option :value="6">最近 6 小时</option><option :value="24">最近 24 小时</option><option :value="168">最近 7 天</option><option :value="720">最近 30 天</option></UiSelect></label>
        <label v-if="w.project.value==='download'" class="check-field"><input v-model="w.downloadFullOnly.value" type="checkbox">只看完整读取</label><span v-if="w.pendingReads.value" class="muted small">读取结果中…</span>
      </div><span class="small muted context-hint">悬停看本轮 · 点击节点看走势</span><button class="button primary scope-run" :disabled="!runNodes.length||w.busy.value||qualityFiltersPending" @click="closeHover();w.openPlan(runNodes)"><Icon name="play"/>{{runLabel(w.project.value)}} · {{qualityFiltersPending&&!w.selectedNodes.value.length?'筛选范围确认中':(w.selectedNodes.value.length?'已选':'筛选')+' '+runNodes.length+' 个节点'}}</button>
    </div>
    <details v-if="w.project.value==='service'||w.project.value==='combined'" class="service-picker-disclosure"><summary>选择检测服务 · 已选 {{w.serviceIds.value.length}} 项 <span>{{selectedServices.slice(0,3).map(s=>s.name).join(' · ')}}</span></summary><ServicePicker v-model="w.serviceIds.value" :catalog="w.catalog.value"/></details>
    <div class="node-toolbar">
      <label class="search-field"><Icon name="search"/><input v-model="w.search.value" type="search" placeholder="搜索节点、机场或地区" aria-label="搜索节点"></label>
      <div class="toolbar-filters">
        <UiSelect v-model="w.airportFilter.value" aria-label="机场筛选"><option value="all">全部机场</option><option v-for="a in chosen" :key="a.id" :value="a.id">{{a.name}}</option></UiSelect>
        <UiSelect class="subscription-filter" v-if="filterProfiles.length>1" v-model="w.subscription.value" aria-label="订阅筛选"><option value="all">全部订阅</option><option v-for="[id,name] in filterProfiles" :key="id" :value="id">{{name}}</option></UiSelect>
        <UiSelect v-model="w.region.value" aria-label="地区筛选"><option value="all">全部地区</option><option v-for="code in filterRegions" :key="code" :value="code">{{nodeRegionLabel(code)}}</option></UiSelect>
        <span id="home-sort-filters" class="node-sort-fields"><UiSelect v-model="w.sort.value" aria-label="节点排序"><option value="region">地区 → 机场</option><option value="airport">机场 → 地区</option><option value="name">按名称排序</option><option v-if="w.project.value==='latency'||w.project.value==='combined'" value="latency">按已保存延迟 / 监测排序</option><option v-if="w.project.value==='download'||w.project.value==='combined'" value="download">按最近下载速度</option><option v-if="w.project.value==='service'||w.project.value==='combined'" value="service">按规则通过 / 全部显示服务</option></UiSelect>
        <UiSelect v-if="w.sort.value==='latency'&&displaySites.length>1" v-model="w.displayTarget.value" aria-label="延迟排序站点"><option v-for="site in displaySites" :key="site.id" :value="site.id">{{site.name}}延迟优先</option></UiSelect>
        <UiSelect v-if="w.sort.value==='airport'&&chosen.length>1&&w.airportFilter.value==='all'" v-model="w.priorityAirportId.value" aria-label="优先机场"><option value="all">机场自然顺序</option><option v-for="a in chosen" :key="a.id" :value="a.id">{{a.name}}优先</option></UiSelect>
        </span><button class="button" :class="{active:w.multiSelect.value}" @click="w.multiSelect.value?w.cancelSelection():w.multiSelect.value=true"><Icon name="select"/>{{w.multiSelect.value?'取消多选':'多选节点'}}</button>
      </div>
    </div>
    <div class="node-list-context"><span>{{w.airportFilter.value==='all'?'全部已选机场':chosen.find(a=>a.id===w.airportFilter.value)?.name}} · {{visibleNodes.length}} 个节点<span v-if="w.sort.value==='region'"> · 同地区按机场、订阅分组</span><span v-else-if="w.sort.value==='airport'&&w.airportFilter.value==='all'&&w.priorityAirportId.value!=='all'"> · {{chosen.find(a=>a.id===w.priorityAirportId.value)?.name}}优先</span><span v-else-if="w.sort.value==='download'"> · 同条件组内比较 · 完整与有效部分分组 · 未测置后</span><span v-else-if="w.sort.value==='service'"> · 同规则条件组内比较 · 完整覆盖先列 · 统一分母</span></span><button v-if="w.notices.value.length" class="text-button" @click="noticeOpen=true">已归入 {{w.notices.value.length}} 条公告</button></div>
    <div v-if="['latency','download','service'].includes(w.sort.value)" class="sort-status" role="status"><span>{{w.sortLoading.value?`读取全部节点 ${w.sortReadCount.value}/${w.proxyNodes.value.length}…`:w.sortError.value|| (w.sortAt.value?'排序截止 '+date(w.sortAt.value)+' · 翻页 / hover 不改变排名':'尚未读取全部节点，仅显示已读记录')}}</span><button class="text-button" :disabled="w.sortLoading.value" @click="w.refreshSort()">更新排序</button></div>
    </div>
    <div class="filter-summary"><button ref="extraFiltersToggle" class="button filters-toggle" :aria-expanded="extraFiltersOpen" :aria-controls="(qualityView?'home-extra-filters ':'')+'home-context-filters home-sort-filters'" @click="extraFiltersOpen=!extraFiltersOpen">{{extraFiltersOpen?'收起筛选':'更多筛选'}}<span>{{qualityFiltersPending?'范围确认中':'符合 '+visibleNodes.length}}</span></button><span class="filter-summary-text">{{filterSummary}}</span></div>
    <div v-if="qualityView" id="home-extra-filters" class="quality-context"><span>统计截止 {{date(qualityCutoff)}} · 每节点读取完整窗口，按条件分组 · 无综合评分</span><UiSelect v-model="protocolFilter" aria-label="协议筛选"><option value="all">全部协议</option><option v-for="p in protocolChoices" :key="p" :value="p">{{p}}</option></UiSelect><UiSelect v-model="qualityGate" aria-label="质量证据筛选"><option value="all">全部证据状态</option><option value="samples">成功样本 ≥5</option><option value="response">样本 ≥5 / 响应率 ≥90%</option><option value="fresh">24 小时内有样本</option><option value="download">有历史有效下载</option><option value="service">最近服务规则通过（任一）</option></UiSelect><UiSelect v-model="qualitySort" aria-label="质量分组排序"><option value="existing">沿用节点排序</option><option value="p50">同条件组 P50 升序</option><option value="p95">同条件组 P95 升序（≥20）</option><option value="rate">同条件组响应率降序</option></UiSelect><label><input v-model="qualityHistory" type="checkbox">显示历史条</label><button class="text-button" :disabled="qualityLoading" @click="readQualityNodes(qualityGate!=='all'||qualitySort!=='existing'?w.proxyNodes.value:pageNodes,true)">{{qualityLoading?'读取中…':'更新质量记录'}}</button></div>
    <div v-if="qualityView" class="quality-compare-action"><button class="button" :disabled="w.selectedNodes.value.length<2" @click="openComparison">比较已选 {{w.selectedNodes.value.length}} 个节点</button></div>
    <p v-if="qualityView&&(qualityGate!=='all'||qualitySort!=='existing')" class="small muted" role="status">{{allQualityReady?`已读固定范围 ${w.proxyNodes.value.length} 个节点 · 当前符合 ${visibleNodes.length} 个 · 读取失败 ${Object.keys(qualityErrors).length} 个 · 存在缺页/读取错误 ${Object.values(qualityData).filter(e=>!e.complete).length} 个（只限制对应类型的证据）`:`正在读取全部 ${w.proxyNodes.value.length} 个节点的保存历史（已读 ${Object.keys(qualityData).length}）；读取完成后应用条件筛选与分组排序`}}。规则通过仍须下钻确认具体业务判据。</p>
    <div v-if="w.multiSelect.value" class="selection-bar" aria-live="polite"><div class="selection-info"><input type="checkbox" :checked="allSelected" :indeterminate="!allSelected&&pageNodes.some(n=>w.selectedKeys.value.includes(key(n)))" aria-label="选择本页全部节点" @change="w.toggleAll(pageNodes)"><strong>已选 {{w.selectedNodes.value.length}} 个节点</strong><button class="text-button" :disabled="qualityFiltersPending" @click="w.toggleAll(visibleNodes)">{{visibleNodes.length&&visibleNodes.every(n=>w.selectedKeys.value.includes(key(n)))?'取消范围选择':'全选筛选范围'}}</button><button v-if="w.selectedKeys.value.length" class="text-button" @click="w.selectedKeys.value=[]">清空已选</button></div><div class="selection-actions"><button class="button primary" :disabled="!w.selectedNodes.value.length||w.busy.value" @click="w.openPlan()"><Icon name="play"/>{{w.project.value==='combined'?'组合检测':projectNames[w.project.value]}}</button><button class="button" :disabled="!w.selectedNodes.value.length" @click="w.monitorNodes.value=w.selectedNodes.value.map(n=>({...n}))"><Icon name="monitor"/>持续监测延迟</button><button class="button ghost" :disabled="!w.selectedNodes.value.length" @click="w.exportSelection().catch(w.fail)">导出</button></div></div>
    <div v-if="w.busy.value" class="live-status"><span class="spinner"/><span>检测正在进行{{w.queue.value.length?` · ${w.done.value}/${w.queue.value.length}`:''}}</span><button class="text-button" @click="w.queueOpen.value=true">查看进度</button><button class="text-button danger" @click="w.cancelTests()">{{w.cancelRequested.value?'正在取消…':'取消检测'}}</button></div>
    <div class="node-list">
      <div v-if="qualityView" class="quality-heading"><span/><span>节点 / 机场 · 勾选比较</span><span>响应时延分布 / 历史成功率 · 下载 · 服务证据</span><span/></div><div v-else class="node-heading" :class="{combined:w.project.value==='combined','multi-target':w.project.value!=='combined'&&(w.project.value!=='latency'||displaySites.length>1)}"><span/><span>节点 / 机场</span><span v-if="w.project.value!=='latency'||displaySites.length<=1">{{w.project.value==='combined'?'延迟 · 下载 · 服务':w.project.value==='latency'?(displaySites.length>1?'':targets.find(t=>t.id===w.displayTarget.value)?.name):w.project.value==='download'?'下载速度':visibleServices.length+' 项服务'}}</span><div v-if="w.project.value==='latency'&&displaySites.length>1" class="station-headings"><span v-for="site in displaySites" :key="site.id">{{site.name}}</span></div><span class="align-right">近期轮次 · 每格含子结果</span><span/></div>
      <article v-for="node in pageNodes" :key="key(node)" class="node-row" @keydown.esc.stop.prevent="closeInline(node)" :class="{selected:w.selectedKeys.value.includes(key(node)),combined:w.project.value==='combined','multi-target':w.project.value!=='combined'&&(w.project.value!=='latency'||displaySites.length>1)}">
        <span class="node-check"><input v-if="w.multiSelect.value||qualityView" type="checkbox" :checked="w.selectedKeys.value.includes(key(node))" :aria-label="`选择 ${nodeDisplayName(node)}`" @change="w.toggleNode(node)"><span v-else class="node-dot" :class="monitoring(node)?'good':'empty'" :title="monitoring(node)?'持续监测中':'未开启持续监测'"/></span>
        <button :id="nodeButtonId(node)" class="node-name-button" :title="node.display_name+' · '+sourceLabel(node)+' · '+node.type" :aria-expanded="expanded(node)" :aria-controls="expanded(node)?nodePanelId(node):undefined" @click="openNodeHistory(node)" @keydown.esc.stop.prevent="closeInline(node)"><span class="country-code">{{node.country_code||'—'}}</span><span class="node-name"><strong>{{nodeDisplayName(node)}}</strong><small>{{sourceLabel(node)}} · {{node.type}}</small></span></button>
        <QualityMetrics v-if="qualityView" :evidence="qualityData[key(node)]" :error="qualityErrors[key(node)]" :target="w.displayTarget.value" :catalog="w.catalog.value"/>
        <div v-else-if="w.project.value==='combined'" class="combined-values">
          <section class="metric-group"><small class="metric-group-heading">延迟</small><div class="node-target-metrics"><div v-for="site in displaySites" :key="site.id"><small>{{site.name}}</small><strong :class="metricPoint(node,site.id)?.tone||'empty'" :title="siteReason(node,site.id)">{{siteMetric(node,site.id)}}</strong><time>{{siteContext(node,site.id)}}</time><span v-if="siteReason(node,site.id).includes('403')" class="metric-note warn">HTTP 403</span></div></div></section>
          <section class="metric-group"><small class="metric-group-heading">下载</small><div class="node-target-metrics"><div><small>下载速度</small><strong :class="downloadMetricTone(node)">{{downloadMetric(node)}}</strong></div></div><small class="download-hover-context">{{downloadMetricContext(node)}}</small></section>
          <section class="metric-group"><small class="metric-group-heading">服务 · {{visibleServices.length}} 项<span v-if="servicePages>1">（第 {{servicePage}} 组）</span></small><div class="node-target-metrics"><div v-for="s in visibleServices" :key="s.service_id"><small :title="s.name">{{s.name}}</small><strong :class="serviceTone(node,s.service_id)">{{serviceMetric(node,s.service_id)}}</strong><time>{{date((w.sort.value==='service'?w.summaryService(node,s.service_id):recentService(w,node,s.service_id))?.finished_at||(w.sort.value==='service'?w.summaryService(node,s.service_id):recentService(w,node,s.service_id))?.requested_at)}}</time></div><div v-if="!visibleServices.length"><strong>尚无服务</strong></div></div><details v-if="httpPoints(node).length||monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])" class="secondary-http"><summary>基础 HTTP · {{monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])?'读取失败':'查看两项端点结果'}}</summary><small v-if="httpPoints(node).length">持续监测 · 基础 HTTP</small><p v-if="monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])" class="small bad" role="alert">监测 HTTP 记录读取失败</p><div v-if="httpPoints(node).length||monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])" class="node-target-metrics monitor-http-metrics"><div v-for="s in monitorHTTPServices" :key="s.id"><small>{{s.name}}</small><strong :class="httpPoints(node,s.id).at(-1)?.tone||'empty'">{{httpMetric(node,s.id)}}</strong></div></div></details></section>
        </div>
        <div v-else class="node-metric">
          <div v-if="w.project.value==='latency'&&displaySites.length>1" class="node-target-metrics"><div v-for="site in displaySites" :key="site.id"><small>{{site.name}}</small><strong :class="metricPoint(node,site.id)?.tone||'empty'" :title="siteReason(node,site.id)">{{siteMetric(node,site.id)}}</strong><time>{{siteContext(node,site.id)}}</time><span v-if="siteReason(node,site.id).includes('403')" class="metric-note warn">HTTP 403</span></div></div>
          <template v-else-if="w.project.value==='service'"><div class="node-target-metrics service-metrics"><div v-for="s in visibleServices" :key="s.service_id"><small :title="s.name">{{s.name}}</small><strong :class="serviceTone(node,s.service_id)">{{serviceMetric(node,s.service_id)}}</strong><time>{{date((w.sort.value==='service'?w.summaryService(node,s.service_id):recentService(w,node,s.service_id))?.finished_at||(w.sort.value==='service'?w.summaryService(node,s.service_id):recentService(w,node,s.service_id))?.requested_at)}}</time></div><div v-if="!visibleServices.length"><strong>尚无服务</strong></div></div><details v-if="httpPoints(node).length||monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])" class="secondary-http"><summary>基础 HTTP · {{monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])?'读取失败':'查看两项端点结果'}}</summary><p v-if="monitorHTTPServices.some(s=>monitorHTTPErrors[key(node)+':'+s.probeType])" class="small bad" role="alert">监测 HTTP 记录读取失败</p><div class="node-target-metrics monitor-http-metrics"><div v-for="s in monitorHTTPServices" :key="s.id"><small>{{s.name}}</small><strong :class="httpPoints(node,s.id).at(-1)?.tone||'empty'">{{httpMetric(node,s.id)}}</strong><time>{{date(httpPoints(node,s.id).at(-1)?.time)}}</time></div></div></details></template>
          <div v-else-if="w.project.value==='download'" class="node-target-metrics download-metrics"><div><small>下载速度</small><strong :class="downloadMetricTone(node)">{{downloadMetric(node)}}</strong></div></div>
          <strong v-else>{{metric(node,w.project.value)}}</strong>
          <small v-if="w.historyReadError(node,w.project.value)" class="bad">读取失败</small><small v-else-if="w.project.value==='service'">{{serviceCoverage(node)}}</small><small v-else-if="w.project.value==='download'" class="download-hover-context" :title="downloadGroup(w.summaryDownload(node)).label">{{downloadMetricContext(node)}}<br>{{downloadGroupLabel(node)}}</small><small v-else-if="w.sort.value==='latency'" :title="w.sortSnapshots.value[key(node)]?.latency?.description">{{latencyGroupLabel(node)}}</small><small v-else>{{date(w.latestForTarget(node,w.displayTarget.value)?.finished_at)}}</small>
        </div>
        <div v-show="!qualityView||qualityHistory" class="node-health compact-history" :class="{'combined-health':w.project.value==='combined'}">
          <div v-if="w.project.value==='latency'||w.project.value==='combined'" class="history-track"><span v-if="w.project.value==='combined'">延迟</span><HealthBars defer :points="sitePoints(node,'all')" :sites="displaySites" label="延迟轮次" @inspect="inspectRound(node,'latency',$event,'all')" @leave="leaveRound" @open="openRound(node,'latency',$event,'all')"/></div>
          <div v-if="w.project.value==='download'||w.project.value==='combined'" class="history-track"><span v-if="w.project.value==='combined'">下载</span><HealthBars defer :points="rowPoints(node,'download')" label="下载测速" @inspect="inspectRound(node,'download',$event)" @leave="leaveRound" @open="openRound(node,'download',$event)"/></div>
          <div v-if="w.project.value==='service'||w.project.value==='combined'" class="history-track"><span v-if="w.project.value==='combined'">服务</span><HealthBars defer :points="presentation.services(node,visibleServiceIds)" :service-ids="visibleServiceIds" label="服务轮次" @inspect="inspectRound(node,'service',$event)" @leave="leaveRound" @open="openRound(node,'service',$event)"/></div>
          <details v-if="(w.project.value==='service'||w.project.value==='combined')&&httpPoints(node).length" class="http-history"><summary>基础 HTTP 历史</summary><div v-for="s in monitorHTTPServices" :key="s.id"><span>{{s.name}}</span><HealthBars :points="httpPoints(node,s.id)" :label="s.name" @inspect="inspectRound(node,'service',$event,w.displayTarget.value,s.id)" @leave="leaveRound" @open="openRound(node,'service',$event,w.displayTarget.value,s.id)"/></div></details>
          <small v-if="monitorErrors[key(node)]" class="bad">监测记录读取失败</small><small v-else><span v-if="monitorData[key(node)]?.length">含持续监测 · 各站独立记录 · </span>{{w.hours.value}} 小时 · {{rowPoints(node,w.project.value).length}} 轮 · 左旧右新</small>
        </div>
        <button class="button row-run" :disabled="w.busy.value" :aria-label="`${runLabel(w.project.value)} ${nodeDisplayName(node)} · ${sourceLabel(node)}`" @click="closeHover();w.openPlan([node])"><Icon name="play"/>{{runLabel(w.project.value)}}</button>
        <section v-if="expanded(node)" :id="nodePanelId(node)" class="node-inline-results" :aria-label="nodeDisplayName(node)+'详情'" @keydown.esc.stop.prevent="closeInline(node)" @mouseenter="keepRound" @mouseleave="leaveRound" @focusin="keepRound">
          <header class="inline-panel-header"><div><strong>{{nodeDisplayName(node)}} · {{projectNames[hoverMode]}}</strong><small>{{sourceLabel(node)}}</small></div><nav class="view-switch" aria-label="节点展开内容"><button :aria-pressed="inlineTab==='round'" :disabled="!activeRound" @click="keepOpen=true;inlineTab='round';keepRound()">本轮数据</button><button :aria-pressed="inlineTab==='history'" @click="expandHistory">完整走势图</button></nav><button class="text-button" :aria-pressed="keepOpen" @click="keepRound();keepOpen=!keepOpen">{{keepOpen?'已固定 · 取消固定':'固定本轮'}}</button><button class="text-button" @click="closeInline(node)">收起</button></header>
          <div v-if="inlineTab==='round'&&activeRound" class="inline-result-columns"><RoundResults v-if="hoverMode==='latency'" :point="activeRound"/><MeasurementResults v-else :point="activeRound" :project="hoverMode"/><div class="inline-history"><p class="small muted">{{hoverMode==='latency'?(activeRound.source==='monitor'?'持续监测 · '+(targets.find(t=>t.id===hoverTarget)?.name||'延迟轮次汇总'):targets.find(t=>t.id===hoverTarget)?.name):hoverMode==='service'?(monitorHTTPServices.find(s=>s.id===hoverService)?.name||w.catalog.value.find(s=>s.service_id===hoverService)?.name||'服务可用性'):'下载速度'}} · 历史走势</p><TrendChart :points="hoverPoints" :unit="hoverMode==='download'?'MiB/s':hoverMode==='service'?'通过':'ms'" label="节点近期走势"/><button class="text-button inline-expand-history" @click="expandHistory">在这里展开完整走势 <Icon name="down"/></button></div></div>
          <InlineHistory v-else :node="node" :nodes="visibleNodes" :project="hoverMode" :source="inlineHistorySource" :monitor-service-id="hoverService" :anchor-points="hoverPoints" :target-ids="inlineHistorySource==='monitor'?[hoverTarget]:w.displayTargets.value" :service-ids="visibleServiceIds"/>
          <details v-if="inlineTab==='round'&&siblingProjects(node).length" class="same-round"><summary>同一轮的其他项目 · {{siblingProjects(node).length}} 项</summary><template v-for="s in siblingProjects(node)" :key="s.project"><RoundResults v-if="s.project==='latency'" :point="s.point"/><MeasurementResults v-else :point="s.point" :project="s.project"/></template></details>
        </section>
      </article>
      <div v-if="!pageNodes.length" class="empty-state"><Icon name="layers"/><h3>{{!chosen.length?'先选择一个机场':!w.nodes.value.length?'还没有缓存的节点':'没有匹配的节点'}}</h3><p>{{!chosen.length?'点击“选择机场”，可同时选择多个机场。':!w.nodes.value.length?'在机场订阅中添加或刷新订阅。':'调整地区、订阅或搜索条件。'}}</p><button class="button" @click="!chosen.length?picker=true:w.page.value='airports'">{{!chosen.length?'选择机场':'管理订阅'}}</button></div>
      <footer class="list-footer"><span>{{visibleNodes.length}} 个节点<span v-if="w.selectedKeys.value.length"> · 已选 {{w.selectedKeys.value.length}}</span></span><div class="health-legend"><span><i class="good"/>成功</span><span><i class="warn"/>受限 / 部分通过</span><span><i class="bad"/>失败</span><span><i class="empty"/>未测</span></div><div class="pagination"><button class="button ghost icon-button" :disabled="currentPage<=1" aria-label="上一页" @click="currentPage--">‹</button><span>{{currentPage}} / {{totalPages}}</span><button class="button ghost icon-button" :disabled="currentPage>=totalPages" aria-label="下一页" @click="currentPage++">›</button></div></footer>
    </div>
    <Modal v-if="picker" title="选择机场" @close="picker=false"><p class="muted">选择会同步更新节点范围，已选节点保留在这个范围内。</p><div class="airport-pick-list"><label v-for="airport in w.airports.value" :key="airport.id" :class="{selected:w.selectedAirportIds.value?.includes(airport.id)}"><input type="checkbox" :checked="w.selectedAirportIds.value?.includes(airport.id)" @change="toggleAirport(airport.id)"><span class="airport-logo">{{airport.name.slice(0,1)}}</span><span><strong>{{airport.name}}</strong><small>{{airport.subscriptions?.length||1}} 个订阅</small></span><span class="muted">{{airportNodeCount(airport.id)}} 个节点</span></label></div><div v-if="!w.airports.value.length" class="empty-state">还没有机场订阅<button class="button" @click="picker=false;w.page.value='airports'">添加机场</button></div><template #footer><button class="button ghost" @click="w.setAirports([])">取消全部</button><button class="button" @click="w.setAirports(w.airports.value.map(a=>a.id))">全选机场</button><button class="button primary" @click="picker=false">完成</button></template></Modal>
    <Modal v-if="noticeOpen" title="机场公告" @close="noticeOpen=false"><div v-for="n in w.notices.value" :key="key(n)" class="notice-row"><small>{{n.profile_name}}</small><p>{{n.display_name}}</p></div></Modal>

    <Modal v-if="compareOpen" title="节点质量横向比较" wide @close="compareOpen=false">
      <p class="quality-compare-meta">{{qualityCompareNodes.length}} 个已选节点 · 截止 {{date(qualityCutoff)}} · 查看不改变测速范围。</p>
      <p class="quality-compare-status" :class="compareCompatible?'muted':'warn'">{{compareCompatible?'延迟最新组条件一致，可比较描述统计。':'延迟不可比较：条件不同、样本不足、未测或读取不完整。'}}</p>
      <p class="comparison-download-status">{{comparisonDownloadStatus}}</p>
      <details class="quality-compare-boundaries"><summary>比较口径与边界</summary><p>延迟按所选站点的最新条件组展示；P95 至少 20 个成功样本，少于 5 个成功样本不排名，缺少出口或地址族/来源证据时只展示原值。下载仅同源、方法、上限、结束类型及已记录的出口地址条件相同时可比较，缺少必要出口证据时不做数值排序；历史有效速度不代表最近检测成功。服务逐项核对同一规则、方法、地址条件和时间，HTTP响应不等于业务可用。完整依据可在各节点的证据行展开。</p></details>
      <p v-if="qualityCompareNodes.length>2" id="comparison-scroll-hint" class="comparison-scroll-hint">← 超出视野时横向滚动；左侧指标固定。聚焦表格可用左右方向键。 →</p>
      <div class="quality-compare" role="region" aria-label="节点逐项比较表" tabindex="0" :aria-describedby="qualityCompareNodes.length>2?'comparison-scroll-hint':undefined" :style="{'--compare-count':qualityCompareNodes.length}">
        <table><colgroup><col class="comparison-label-column"><col v-for="n in qualityCompareNodes" :key="key(n)"></colgroup>
          <thead><tr><th scope="col">指标</th><th v-for="n in qualityCompareNodes" :key="key(n)" scope="col"><strong>{{nodeDisplayName(n)}}</strong><small>{{sourceLabel(n)}}</small><small>{{n.type}}</small></th></tr></thead>
          <tbody><tr v-for="row in ([{id:'distribution',label:'延迟分布'},{id:'response',label:'成功率 / 样本'},{id:'download',label:'下载'},{id:'service',label:'服务结论'},{id:'time',label:'测量时间'},{id:'details',label:'完整证据'}] as const)" :key="row.id"><th scope="row">{{row.label}}</th><td v-for="n in qualityCompareNodes" :key="key(n)"><QualityMetrics :comparison-field="row.id" :evidence="qualityData[key(n)]" :error="qualityErrors[key(n)]" :target="w.displayTarget.value" :catalog="w.catalog.value"/></td></tr>
          <tr><th scope="row">原始历史</th><td v-for="n in qualityCompareNodes" :key="key(n)"><button class="button" @click="compareOpen=false;openNodeHistory(n)">查看原始历史</button></td></tr></tbody>
        </table>
      </div>
    </Modal>
  </section>
</template>
